import { useMemo, useState, type CSSProperties } from 'react'
import { useLiveQuery } from 'dexie-react-hooks'
import { differenceInCalendarDays, parseISO } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { Card, Field, Sheet } from '@/components/ui'
import { useSession } from '@/app/session'
import { db } from '@/db/db'
import { useI18n } from '@/i18n'
import { Temu } from './Temu'
import { growth, LINEAGES, STAGES, type Lineage, type Mood } from './model'
import {
  computeStreak,
  dayKeyFor,
  restRemaining,
  type ContributionKind,
  type DayRecord,
} from './streak'
import { shareTemu } from './share'
import habitatUrl from '@/assets/temu-habitat.webp'
import './companion.css'

/**
 * Temu — the companion screen.
 *
 * Every number on this page is about *both* people or about neither. There is
 * deliberately no per-partner statistic, no comparison, and no way to see who
 * has been "better". See docs/ART_BIBLE.md §7.
 */

const CONTRIBUTIONS: ContributionKind[] = [
  'connect',
  'appreciate',
  'coordinate',
  'care',
  'household',
  'reflect',
  'plan',
  'repair',
  'play',
  'memory',
]

const CONTRIB_ICON: Record<ContributionKind, Parameters<typeof Icon>[0]['name']> = {
  connect: 'checkin',
  appreciate: 'date',
  coordinate: 'calendar',
  care: 'heart',
  household: 'tasks',
  reflect: 'self',
  plan: 'mentalload',
  repair: 'repair',
  play: 'memories',
  memory: 'memories',
}

export default function Companion() {
  const { t } = useI18n()
  const { profile, partner } = useSession()
  const [picking, setPicking] = useState(false)
  const [naming, setNaming] = useState(false)
  const [draftName, setDraftName] = useState('')
  const [celebrate, setCelebrate] = useState(false)
  const [message, setMessage] = useState<string | null>(null)

  const state = useLiveQuery(async () => {
    const [records, meta] = await Promise.all([
      db.settings.get('temu.days'),
      db.settings.get('temu.meta'),
    ])
    return {
      days: (records?.value as DayRecord[]) ?? [],
      meta: (meta?.value as { name?: string; lineage?: Lineage; startedAt?: string }) ?? {},
    }
  }, [])

  const now = new Date()
  const days = state?.days ?? []
  const meta = state?.meta ?? {}

  const streak = useMemo(() => computeStreak(days, now), [days])
  const relationshipDays = meta.startedAt
    ? differenceInCalendarDays(now, parseISO(meta.startedAt))
    : streak.pairDays
  const g = useMemo(() => growth(streak.pairDays, relationshipDays), [streak.pairDays, relationshipDays])

  const lineage: Lineage = meta.lineage ?? 'awal'
  const canPickLineage = streak.pairDays >= 100 && !meta.lineage

  // Mood is about the day, never about the relationship.
  const mood: Mood = celebrate
    ? 'celebrate'
    : streak.today.complete
      ? 'happy'
      : streak.today.a || streak.today.b
        ? 'waiting'
        : streak.current === 0 && streak.pairDays > 0
          ? 'sleepy'
          : 'calm'

  if (!profile) return null

  async function writeDays(next: DayRecord[]) {
    await db.settings.put({ key: 'temu.days', value: next })
  }
  async function writeMeta(patch: Record<string, unknown>) {
    await db.settings.put({ key: 'temu.meta', value: { ...meta, ...patch } })
  }

  /**
   * Records the *active profile's* half. On a shared device, whichever profile
   * is switched in is the one contributing — there is no way to fill in the
   * other person's half, by design.
   */
  async function contribute(kind: ContributionKind) {
    const key = dayKeyFor(now)
    const isA = !partner || profile!.id < partner.id
    const next = [...days]
    const i = next.findIndex((d) => d.date === key)
    const rec: DayRecord = i >= 0 ? { ...next[i]! } : { date: key }
    if (isA) rec.a = kind
    else rec.b = kind
    if (i >= 0) next[i] = rec
    else next.push(rec)

    const before = computeStreak(days, now).pairDays
    await writeDays(next)
    if (!meta.startedAt) await writeMeta({ startedAt: key })

    if (computeStreak(next, now).pairDays > before) {
      setCelebrate(true)
      setTimeout(() => setCelebrate(false), 1400)
    }
  }

  async function takeRest() {
    const key = dayKeyFor(now)
    const next = days.filter((d) => d.date !== key)
    next.push({ date: key, rest: true })
    await writeDays(next)
  }

  async function repair() {
    if (!streak.repairable) return
    const next = days.filter((d) => d.date !== streak.repairable)
    next.push({ date: streak.repairable, repaired: true })
    await writeDays(next)
  }

  async function share() {
    const ok = await shareTemu({
      growth: g,
      lineage,
      name: meta.name ?? t('temu.title'),
      pairDays: streak.pairDays,
      streak: streak.current,
      caption: t('temu.shareCaption', { name: meta.name ?? t('temu.title'), days: streak.pairDays }),
    })
    if (ok) setMessage(t('temu.shareDone'))
  }

  return (
    <div className="stack">
      <div className="row row--between">
        <h1>{t('temu.title')}</h1>
        <button className="btn btn--ghost btn--sm" onClick={share}>
          <Icon name="export" size={16} /> {t('temu.share')}
        </button>
      </div>

      {message && (
        <p className="banner" role="status">
          <Icon name="info" size={18} /> {message}
        </p>
      )}

      <div className="temu-focus">
      {/* ---- the stage ---- */}
      <section
        className={`temu-stage temu-stage--${lineage}`}
        style={{ '--temu-habitat': `url("${habitatUrl}")` } as CSSProperties}
      >
        <div className="temu-stage__sky" aria-hidden="true" />
        <Temu
          growth={g}
          lineage={lineage}
          mood={mood}
          size={300}
          celebrate={celebrate}
          pulse={{ a: streak.today.a, b: streak.today.b }}
          label={`${meta.name ?? t('temu.title')} — ${t(g.stage.name)}`}
        />
        <div className="temu-stage__plate">
          <button
            className="temu-stage__name"
            onClick={() => {
              setDraftName(meta.name ?? '')
              setNaming(true)
            }}
          >
            {meta.name ?? t('temu.unnamed')}
            <Icon name="settings" size={14} />
          </button>
          <p className="temu-stage__stage">{t(g.stage.name)}</p>
          <p className="temu-stage__form">
            {t('temu.formNumber', { n: g.stage.evolution ?? 1, total: STAGES.length })}
          </p>
          <p className="temu-stage__blurb">{t(g.stage.blurb)}</p>
        </div>
      </section>

      {/* ---- the day ---- */}
      <div className="temu-today">
      <Card title={t('temu.todayTitle')} icon="heart">
        <p className="card__hint">
          {streak.today.complete
            ? t('temu.todayBoth')
            : streak.today.a || streak.today.b
              ? t('temu.todayOne')
              : t('temu.todayNone')}
        </p>

        <div className="temu-halves">
          <Half label={t('temu.myHalf')} done={mine(streak, profile.id, partner?.id)} t={t} />
          <Half
            label={partner ? t('temu.partnerHalf', { name: partner.displayName }) : t('temu.partnerHalfGeneric')}
            done={theirs(streak, profile.id, partner?.id)}
            t={t}
          />
        </div>

        {!mine(streak, profile.id, partner?.id) && (
          <>
            <p className="card__hint" style={{ marginTop: 'var(--space-3)' }}>
              {t('temu.contributeHint')}
            </p>
            <div className="temu-actions">
              {CONTRIBUTIONS.map((k) => (
                <button key={k} className="temu-action" onClick={() => contribute(k)}>
                  <Icon name={CONTRIB_ICON[k]} size={18} animate />
                  <span>{t(`contrib.${k}` as const)}</span>
                </button>
              ))}
            </div>
          </>
        )}
      </Card>
      </div>
      </div>

      {/* ---- the run ---- */}
      <div className="temu-after">
      <Card title={t('temu.streak', { n: streak.current })} icon="date" hint={t('temu.streakBody')}>
        <div className="temu-stats">
          <Stat value={streak.pairDays} label={t('temu.pairDays', { n: streak.pairDays })} />
          <Stat value={streak.longest} label={t('temu.longest', { n: streak.longest })} />
          <Stat value={relationshipDays} label={t('temu.together', { n: relationshipDays })} />
        </div>

        {streak.repairable && (
          <div className="banner banner--warn" style={{ marginTop: 'var(--space-3)' }}>
            <Icon name="repair" size={18} />
            <span className="stack stack--tight">
              {t('temu.repairDesc')}
              <button className="btn btn--soft btn--sm" onClick={repair} style={{ alignSelf: 'flex-start' }}>
                {t('temu.repairDo')}
              </button>
            </span>
          </div>
        )}

        <div className="row" style={{ marginTop: 'var(--space-3)' }}>
          <span className="chip chip--mint">{t('temu.restLeft', { n: restRemaining(streak) })}</span>
          {restRemaining(streak) > 0 && !streak.today.complete && (
            <button className="btn btn--ghost btn--sm" onClick={takeRest}>
              {t('temu.takeRest')}
            </button>
          )}
        </div>
        <p className="card__hint" style={{ marginTop: 'var(--space-2)' }}>
          {t('temu.restDesc')}
        </p>
      </Card>

      {/* ---- what's next ---- */}
      <Card title={g.next ? t('temu.nextForm', { n: g.next.evolution ?? 1, total: STAGES.length }) : t('temu.gallery')} icon="cycle">
        {g.next ? (
          <>
            <span
              className="goal__bar"
              role="progressbar"
              aria-valuenow={Math.round(g.progress * 100)}
              aria-valuemin={0}
              aria-valuemax={100}
              aria-label={t(g.next.name)}
            >
              <span style={{ width: `${Math.max(3, g.progress * 100)}%` }} />
            </span>
            <p className="card__hint" style={{ marginTop: 'var(--space-2)' }}>
              {g.gate === 'both'
                ? t('temu.gate.both', { days: g.pairDaysToNext, calendar: g.daysToNext })
                : g.gate === 'pairDays'
                  ? t('temu.gate.pairDays', { n: g.pairDaysToNext })
                  : g.gate === 'time'
                    ? t('temu.gate.time', { n: g.daysToNext })
                    : ''}
            </p>
          </>
        ) : (
          <p className="card__hint">
            {t('temu.gate.done')} · {t('temu.rings', { n: g.legacyRings })}
          </p>
        )}
      </Card>
      </div>

      {/* ---- lineage ---- */}
      {canPickLineage && (
        <Card title={t('temu.lineage')} icon="cycle" hint={t('temu.lineagePick')}>
          <button className="btn btn--block" onClick={() => setPicking(true)}>
            {t('temu.lineage')}
          </button>
        </Card>
      )}

      <p className="disclaimer">{t('temu.notAScore')}</p>

      <Sheet open={picking} onClose={() => setPicking(false)} title={t('temu.lineage')}>
        <div className="stack">
          <p className="card__hint">{t('temu.lineagePick')}</p>
          <div className="temu-lineages">
            {LINEAGES.map((l) => (
              <button
                key={l}
                className="temu-lineage"
                onClick={async () => {
                  await writeMeta({ lineage: l })
                  setPicking(false)
                  setCelebrate(true)
                  setTimeout(() => setCelebrate(false), 1400)
                }}
              >
                <Temu growth={g} lineage={l} mood="happy" size={92} />
                <strong>{t(`temu.lineage.${l}` as const)}</strong>
                <span>{t(`temu.lineage.${l}.desc` as const)}</span>
              </button>
            ))}
          </div>
        </div>
      </Sheet>

      <Sheet open={naming} onClose={() => setNaming(false)} title={t('temu.namePrompt')}>
        <div className="stack">
          <Field label={t('temu.namePrompt')}>
            {(p) => (
              <input
                {...p}
                type="text"
                value={draftName}
                placeholder={t('temu.namePlaceholder')}
                onChange={(e) => setDraftName(e.target.value)}
              />
            )}
          </Field>
          <button
            className="btn btn--block"
            disabled={!draftName.trim()}
            onClick={async () => {
              await writeMeta({ name: draftName.trim() })
              setNaming(false)
            }}
          >
            {t('common.save')}
          </button>
        </div>
      </Sheet>
    </div>
  )
}

/** On a shared device the lower profile id is "A" — stable and arbitrary. */
function mine(s: ReturnType<typeof computeStreak>, me: string, them?: string): boolean {
  const isA = !them || me < them
  return isA ? s.today.a : s.today.b
}
function theirs(s: ReturnType<typeof computeStreak>, me: string, them?: string): boolean {
  const isA = !them || me < them
  return isA ? s.today.b : s.today.a
}

function Half({ label, done, t }: { label: string; done: boolean; t: ReturnType<typeof useI18n>['t'] }) {
  return (
    <div className={`temu-half ${done ? 'temu-half--done' : ''}`}>
      <Icon name={done ? 'check' : 'heart'} size={18} />
      <span className="stack stack--tight">
        <strong>{label}</strong>
        <span>{done ? t('temu.done') : t('temu.notYet')}</span>
      </span>
    </div>
  )
}

function Stat({ value, label }: { value: number; label: string }) {
  return (
    <div className="temu-stat">
      <strong>{value}</strong>
      <span>{label.replace(/^\d+\s*/, '')}</span>
    </div>
  )
}

export { STAGES }
